import pytest

from wemake_python_styleguide.violations.refactoring import (
    FalsyConstantCompareViolation,
)
from wemake_python_styleguide.visitors.ast.compares import (
    WrongConstantCompareVisitor,
)


@pytest.mark.parametrize('code', [
    'assert some == []',
    'assert [] == some',
    'assert some == [], "message"',
    'assert [] == some, "message"',
])
def test_ignores_falsy_compare_in_assert(assert_errors, parse_ast_tree, code, default_options):
    tree = parse_ast_tree(code)

    visitor = WrongConstantCompareVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


@pytest.mark.parametrize('code', [
    'if some == []: ...',
    'if [] == some: ...',
])
def test_reports_falsy_compare_outside_assert(assert_errors, parse_ast_tree, code, default_options):
    tree = parse_ast_tree(code)

    visitor = WrongConstantCompareVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [FalsyConstantCompareViolation])
